        // detached HEAD and drop the guard branch (unless a commit already moved it, then it is the only reference).
        if (guardBranch) {
          const back = git(entry.path, ["switch", "--detach", "--end-of-options", guardBranch], { allowFailure: true });
          if (back.status === 0) {
